var IB_LEN = { AD:24,AE:23,AT:20,BE:16,BG:22,CH:21,CY:28,CZ:24,DE:22,DK:18,EE:20,ES:24,
  FI:18,FR:27,GB:22,GI:23,GR:27,HR:21,HU:28,IE:22,IL:23,IS:26,IT:27,LI:21,LT:20,LU:20,
  LV:21,MC:27,MT:31,NL:18,NO:15,PL:28,PT:25,RO:24,RS:22,SA:24,SE:24,SI:19,SK:24,SM:27,TR:26,UA:29 };
function ibNormalize(s){ return String(s==null?'':s).toUpperCase().replace(/[\s-]/g,''); }
function ibMod97(str){
  var rem=0;
  for(var i=0;i<str.length;i++) rem=(rem*10+(str.charCodeAt(i)-48))%97;
  return rem;
}
function ibToNumeric(iban){
  var re=iban.slice(4)+iban.slice(0,4), out='';
  for(var i=0;i<re.length;i++){
    var c=re.charCodeAt(i);
    if(c>=65 && c<=90) out += (c-55);
    else out += re[i];
  }
  return out;
}
function ibValidate(input){
  var s=ibNormalize(input);
  if(!s) return { error:'\u8bf7\u8f93\u5165 IBAN' };
  if(!/^[A-Z]{2}[0-9]{2}[A-Z0-9]+$/.test(s))
    return { error:null, valid:false, reason:'\u683c\u5f0f\u5e94\u4e3a 2 \u4f4d\u56fd\u5bb6\u7801 + 2 \u4f4d\u6821\u9a8c\u4f4d + \u5b57\u6bcd\u6570\u5b57', iban:s };
  var cc=s.slice(0,2), want=IB_LEN[cc];
  if(want && s.length!==want)
    return { error:null, valid:false, reason:cc+' \u7684 IBAN \u957f\u5ea6\u5e94\u4e3a '+want+'\uff0c\u5b9e\u9645 '+s.length, iban:s, country:cc };
  var mod=ibMod97(ibToNumeric(s));
  return { error:null, valid:mod===1, iban:s, country:cc, known:!!want, mod:mod,
           reason: mod===1 ? '' : 'mod-97 \u6821\u9a8c\u5931\u8d25\uff08\u4f59\u6570 '+mod+'\uff0c\u5e94\u4e3a 1\uff09' };
}
function ibFormat(input){
  var s=ibNormalize(input);
  return s.replace(/(.{4})/g,'$1 ').trim();
}
function ibCheckDigits(cc, bban){
  var body=ibNormalize(cc)+'00'+ibNormalize(bban);
  var mod=ibMod97(ibToNumeric(body));
  var cd=98-mod;
  return (cd<10?'0':'')+cd;
}
function ibLuhn(num){
  var s=String(num==null?'':num).replace(/[\s-]/g,'');
  if(!/^\d+$/.test(s) || s.length<2) return { valid:false, reason:'\u8bf7\u8f93\u5165\u81f3\u5c11 2 \u4f4d\u6570\u5b57' };
  var sum=0, alt=false;
  for(var i=s.length-1;i>=0;i--){
    var d=s.charCodeAt(i)-48;
    if(alt){ d*=2; if(d>9) d-=9; }
    sum+=d; alt=!alt;
  }
  return { valid: sum%10===0, sum:sum, reason: sum%10===0 ? '' : 'Luhn \u6821\u9a8c\u4f4d\u4e0d\u6b63\u786e' };
}
